SELECT
CASE WHEN L.LEDGER_NAME IN ('Scheme Ledger AU','Processor QLD Ledger AU','Scheme Secondary Ledger') THEN 10000 WHEN L.LEDGER_NAME = 'Service Co Ledger AU' THEN -1 WHEN L.LEDGER_NAME IN ('Scheme WA Ledger AU','Processor WA Ledger AU','Scheme WA Secondary Ledger AU') THEN 10001 WHEN L.LEDGER_NAME IN ('Scheme VIC Ledger','Scheme VIC NOP Ledger') THEN 10002 ELSE NULL END AS MULTI_SCHEME_ID
, CASE WHEN L.LEDGER_NAME IN ('Scheme Ledger AU','Processor QLD Ledger AU','Scheme Secondary Ledger') THEN 'QLD' WHEN L.LEDGER_NAME = 'Service Co Ledger AU' THEN 'CES' WHEN L.LEDGER_NAME IN ('Scheme WA Ledger AU','Processor WA Ledger AU','Scheme WA Secondary Ledger AU') THEN 'WA' WHEN L.LEDGER_NAME IN ('Scheme VIC Ledger','Scheme VIC NOP Ledger') THEN 'VIC' ELSE NULL END AS SCHEME
, L.LEDGER_NAME AS LEDGER_NAME
, L.CHART_OF_ACCOUNT AS CHART_OF_ACCOUNT
, L.LEDGER_DESC AS LEDGER_DESC
, CASE WHEN L.LEDGER_NAME IN ('Scheme Ledger AU','Processor QLD Ledger AU','Scheme Secondary Ledger') THEN 'Scheme Ledger' WHEN L.LEDGER_NAME = 'Service Co Ledger AU' THEN 'Service Co Ledg' WHEN L.LEDGER_NAME IN ('Scheme WA Ledger AU','Processor WA Ledger AU','Scheme WA Secondary Ledger AU') THEN 'WA Ledger' WHEN L.LEDGER_NAME = 'Scheme VIC Ledger' THEN 'VIC Ledger' WHEN L.LEDGER_NAME = 'Scheme VIC NOP Ledger' THEN 'VIC NOP Ledger' ELSE NULL END AS FISCAL_PERIOD_PRIMARY
, CASE WHEN L.LEDGER_NAME IN ('Scheme Ledger AU','Processor QLD Ledger AU','Scheme Secondary Ledger') THEN 'Scheme Sec Cal' WHEN L.LEDGER_NAME = 'Service Co Ledger AU' THEN 'Service Co Ledg' WHEN L.LEDGER_NAME IN ('Scheme WA Ledger AU','Processor WA Ledger AU','Scheme WA Secondary Ledger AU') THEN 'SchemeWA Sec'  ELSE NULL END AS FISCAL_PERIOD_SECONDARY
, CASE WHEN L.LEDGER_NAME IN ('Scheme Ledger AU','Processor QLD Ledger AU','Scheme Secondary Ledger','Scheme WA Ledger AU','Processor WA Ledger AU','Scheme WA Secondary Ledger AU') THEN 'Account Scheme Ledger-Account Scheme Ledger Current' WHEN L.LEDGER_NAME = 'Service Co Ledger AU' THEN 'Account Service Co Ledger-Account Service Co Ledger Current' WHEN L.LEDGER_NAME = 'Scheme VIC Ledger' THEN 'Account VIC Scheme Ledger-Account VIC Scheme Ledger Current' WHEN L.LEDGER_NAME = 'Scheme VIC NOP Ledger' THEN 'Account Scheme VIC NOP Ledger-Account Scheme VIC NOP Ledger Current' ELSE 'Stale Account' END AS ACCOUNT_TREE_CODE
, CASE WHEN L.LEDGER_NAME IN ('Scheme Ledger AU','Processor QLD Ledger AU','Scheme Secondary Ledger') THEN 'Company Scheme Ledger-Company Scheme Ledger Current' WHEN L.LEDGER_NAME = 'Service Co Ledger AU' THEN 'Company Service Co Ledger-Company Service Co Ledger Current' WHEN L.LEDGER_NAME IN ('Scheme WA Ledger AU','Processor WA Ledger AU','Scheme WA Secondary Ledger AU') THEN 'Company WARRRL WA Ledger-Company WARRRL WA Ledger Current' WHEN L.LEDGER_NAME = 'Scheme VIC Ledger' THEN 'Company Scheme VIC Ledger-Company Scheme VIC Ledger Current' WHEN L.LEDGER_NAME = 'Scheme VIC NOP Ledger' THEN 'Company Scheme VIC NOP Ledger-Company Scheme VIC NOP Ledger Current' ELSE NULL END AS ENTITY_TREE_CODE
, CASE WHEN L.LEDGER_NAME IN ('Scheme Ledger AU','Processor QLD Ledger AU','Scheme Secondary Ledger') THEN 'Cost Center Scheme Ledger-Cost Center Scheme Ledger Current' WHEN L.LEDGER_NAME = 'Service Co Ledger AU' THEN 'Cost Center Service Co Ledger-Cost Center Service Co Ledger Current' WHEN L.LEDGER_NAME IN ('Scheme WA Ledger AU','Processor WA Ledger AU','Scheme WA Secondary Ledger AU') THEN 'Cost Center WARRRL WA Ledger-Cost Center WARRRL WA Ledger Current' WHEN L.LEDGER_NAME = 'Scheme VIC Ledger' THEN 'Cost Center Scheme VIC Ledger-Cost Center Scheme VIC Ledger Current' WHEN L.LEDGER_NAME = 'Scheme VIC NOP Ledger' THEN 'Cost Center Scheme VIC NOP Ledger-CC Scheme VIC NOP Ledger Current' ELSE NULL END AS COST_CENTRE_TREE_CODE
, CASE WHEN L.LEDGER_NAME IN ('Scheme Ledger AU','Processor QLD Ledger AU','Scheme Secondary Ledger') THEN 'Mat Type Scheme Ledger-Mat Type Scheme Ledger Current' WHEN L.LEDGER_NAME IN ('Scheme WA Ledger AU','Processor WA Ledger AU','Scheme WA Secondary Ledger AU') THEN 'Mat Type WARRRL WA Ledger-Mat Type WARRRL WA Ledger Current' WHEN L.LEDGER_NAME = 'Scheme VIC Ledger' THEN 'Mat Type Scheme VIC Ledger-Mat Type Scheme VIC Ledger Current' WHEN L.LEDGER_NAME = 'Scheme VIC NOP Ledger' THEN 'Mat Type Scheme VIC NOP Ledger-Mat Type Scheme VIC NOP Ledger Current' ELSE NULL END AS MAT_TYPE_TREE_CODE
, CASE WHEN L.LEDGER_NAME IN ('Scheme Ledger AU','Processor QLD Ledger AU','Scheme Secondary Ledger') THEN 'Spare Scheme Ledger-Spare Scheme Ledger Current' WHEN L.LEDGER_NAME = 'Service Co Ledger AU' THEN 'Spare Service Co Ledger-Spare Service Co Ledger Current' WHEN L.LEDGER_NAME IN ('Scheme WA Ledger AU','Processor WA Ledger AU','Scheme WA Secondary Ledger AU') THEN 'Spare WARRRL WA Ledger-Spare WARRRL WA Ledger Current' WHEN L.LEDGER_NAME = 'Scheme VIC Ledger' THEN 'Spare Scheme VIC Ledger-Spare Scheme VIC Ledger Current' WHEN L.LEDGER_NAME = 'Scheme VIC NOP Ledger' THEN 'Spare Scheme VIC NOP Ledger-Spare Scheme VIC NOP Ledger Current' ELSE NULL END AS PROJECT_TREE_CODE
, SYSDATE() AS INSERT_DATE_UTC
FROM
{{ source('CES_ERP', 'GL_LEDGER') }} AS L
WHERE CHART_OF_ACCOUNT <> 'DO NOT USE - WARRRL WA Ledger'
